-- JOB DB-SEC stage 2 check (read-only)
select 'anon_secdef_count', count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and has_function_privilege('anon',p.oid,'EXECUTE');
select 'still_anon_revoked_list', p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and has_function_privilege('anon',p.oid,'EXECUTE') and p.proname = any(array['promote_next_waitlisted','tg_bookings_auto_promote','check_and_book_seats','promote_waitlisted_by_id','get_unit_setup','save_unit_setup','can_view_unit_setup','event_capacity_summary']);
select 'keep', p.proname, has_function_privilege('anon',p.oid,'EXECUTE') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname = any(array['get_join_us_costs','get_meeting_pattern','get_next_public_meeting','get_upcoming_public_meetings','get_officers_public','get_officers_public_year','get_public_booking_details','get_public_lodge_figures','get_public_unit_profile','get_published_meeting_for_event','officer_signatures_enabled','is_event_published','current_officer_holder','current_unit_id','officer_lookup_unit','get_lodge_identity']) order by 2;
select 'auth_kept', p.proname, has_function_privilege('authenticated',p.oid,'EXECUTE'), has_function_privilege('service_role',p.oid,'EXECUTE') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('promote_next_waitlisted','check_and_book_seats','get_unit_setup','save_unit_setup','last_engagement_date');
select 'table_anon', c.relname, c.relacl::text ~ 'anon=' from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('units','unit_settings','unit_settings_audit','unit_domains','member_signatures','signature_event_audit','signature_usage_audit');
select 'defacl', defaclobjtype, defaclacl from pg_default_acl where defaclrole='postgres'::regrole and defaclnamespace='public'::regnamespace;
select 'trigger_owner', proname, prosecdef, proowner::regrole from pg_proc where proname in ('tg_bookings_auto_promote','promote_next_waitlisted');
